const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define the region between Kakhovka and North Crimean Canals
  // This area is in southern Ukraine (Kherson Oblast)
  const region = ee.Geometry.Polygon([
    [[33.3, 46.5], [34.2, 46.5], [34.2, 46.9], [33.3, 46.9], [33.3, 46.5]]
  ]);

  // Cloud masking function for Sentinel-2
  function maskS2clouds(image) {
    const scl = image.select('SCL');
    const mask = scl.neq(3).and(scl.neq(8)).and(scl.neq(9)).and(scl.neq(10));
    return image.updateMask(mask);
  }

  // Get May 2023 imagery
  const mayCol = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(region)
    .filterDate('2023-05-14', '2023-05-20')
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30))
    .map(maskS2clouds);

  const maySize = mayCol.size().getInfo();
  console.log(`May images found: ${maySize}`);

  if (maySize === 0) {
    console.log("No images found for May 2023");
    console.log("<answer>C1</answer>");
    return;
  }

  // Get June 2023 imagery
  const juneCol = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(region)
    .filterDate('2023-06-15', '2023-06-21')
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30))
    .map(maskS2clouds);

  const juneSize = juneCol.size().getInfo();
  console.log(`June images found: ${juneSize}`);

  if (juneSize === 0) {
    console.log("No images found for June 2023");
    console.log("<answer>C1</answer>");
    return;
  }

  // Create median composites
  const mayImg = mayCol.median();
  const juneImg = juneCol.median();

  // Calculate NDVI for both periods (lower NDVI = browner/less vegetation)
  const mayNDVI = mayImg.normalizedDifference(['B8', 'B4']).rename('NDVI');
  const juneNDVI = juneImg.normalizedDifference(['B8', 'B4']).rename('NDVI');

  // Calculate mean NDVI and pixel counts
  const mayStats = mayNDVI.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const juneStats = juneNDVI.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const mayNDVIval = mayStats.NDVI_mean;
  const mayCount = mayStats.NDVI_count;
  const juneNDVIval = juneStats.NDVI_mean;
  const juneCount = juneStats.NDVI_count;

  console.log(`May NDVI: ${mayNDVIval?.toFixed(3)}, Valid pixels: ${mayCount}`);
  console.log(`June NDVI: ${juneNDVIval?.toFixed(3)}, Valid pixels: ${juneCount}`);

  // Check for no valid pixels
  if (!mayCount || mayCount === 0 || !juneCount || juneCount === 0) {
    console.log("No valid pixels after cloud masking");
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for invalid values
  if (mayNDVIval === null || juneNDVIval === null || 
      mayNDVIval === undefined || juneNDVIval === undefined ||
      isNaN(mayNDVIval) || isNaN(juneNDVIval) ||
      mayNDVIval > 1 || mayNDVIval < -1 || juneNDVIval > 1 || juneNDVIval < -1) {
    console.log("Invalid NDVI values calculated");
    console.log("<answer>C3</answer>");
    return;
  }

  // Browner = lower NDVI (less green vegetation, more bare soil/senescent crops)
  const ndviDiff = juneNDVIval - mayNDVIval;
  console.log(`NDVI difference (June - May): ${ndviDiff.toFixed(3)}`);

  if (juneNDVIval < mayNDVIval) {
    console.log("June fields are browner (lower NDVI) than May");
    console.log("<answer>A</answer>");
  } else {
    console.log("June fields are NOT browner than May");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
